import { NextRequest, NextResponse } from 'next/server';

import { requireBearerToken } from '@/server/auth/http';
import { ApiError, handleApiError } from '@/server/http';
import { logger } from '@/server/logger';
import {
  createOpenfortEncryptionSession,
  OpenfortEncryptionSessionError,
  verifyOpenfortAccessToken,
} from '@/server/openfort/session';

export async function POST(request: NextRequest) {
  try {
    const accessToken = requireBearerToken(request);
    const body = await request.json().catch(() => ({}));
    const requestedUserId =
      body && typeof body === 'object' && 'user_id' in body
        ? body.user_id
        : undefined;

    if (typeof requestedUserId !== 'string' || !requestedUserId.trim()) {
      throw new ApiError('BAD_REQUEST', 'Openfort user ID is required.');
    }

    const session = await verifyOpenfortAccessToken(accessToken);

    if (session.user.id !== requestedUserId) {
      throw new ApiError(
        'FORBIDDEN',
        'Openfort user mismatch for encryption session.'
      );
    }

    const encryptionSession = await createOpenfortEncryptionSession();

    return NextResponse.json({ session: encryptionSession });
  } catch (err) {
    if (err instanceof OpenfortEncryptionSessionError) {
      logger.error(
        {
          err,
          code: err.code,
          hint: err.hint,
          service: err.service,
          envVars: err.envVars,
        },
        'Encryption session configuration error'
      );
      return NextResponse.json(
        {
          code: err.code,
          message: err.message,
          detail: err.hint,
          fields: {
            service: err.service,
            envVars: err.envVars.join(', '),
          },
        },
        { status: err.status }
      );
    }

    logger.error({ err }, 'Encryption session error');
    return handleApiError(err);
  }
}

import 'server-only';

import Openfort from '@openfort/openfort-node';

import { ApiError } from '@/server/http';
import { logger } from '@/server/logger';
import { requireServerEnv } from '@/server/env';

export interface VerifiedOpenfortSession {
  user: {
    id: string;
    email?: string | null;
    name?: string | null;
    phoneNumber?: string | null;
  };
  session: {
    id?: string | null;
    expiresAt?: string | null;
  };
}

let cachedClient: Openfort | undefined;

function getOpenfortClient() {
  if (cachedClient) return cachedClient;

  const { openfort } = requireServerEnv(['openfort']);
  cachedClient = new Openfort(openfort.secretKey!, {
    basePath: openfort.baseUrl,
    publishableKey: openfort.publishableKey,
  });

  return cachedClient;
}

function normalizeOpenfortSession(session: unknown): VerifiedOpenfortSession {
  if (!session || typeof session !== 'object') {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  const value = session as {
    user?: {
      id?: unknown;
      email?: unknown;
      name?: unknown;
      phoneNumber?: unknown;
    };
    session?: {
      id?: unknown;
      expiresAt?: unknown;
    };
  };
  const userId = value.user?.id;

  if (typeof userId !== 'string' || !userId.trim()) {
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }

  return {
    user: {
      id: userId,
      email:
        typeof value.user?.email === 'string' ? value.user.email : undefined,
      name: typeof value.user?.name === 'string' ? value.user.name : undefined,
      phoneNumber:
        typeof value.user?.phoneNumber === 'string'
          ? value.user.phoneNumber
          : undefined,
    },
    session: {
      id: typeof value.session?.id === 'string' ? value.session.id : undefined,
      expiresAt:
        typeof value.session?.expiresAt === 'string'
          ? value.session.expiresAt
          : undefined,
    },
  };
}

export async function verifyOpenfortAccessToken(accessToken: string) {
  try {
    const session = await getOpenfortClient().iam.getSession({ accessToken });
    return normalizeOpenfortSession(session);
  } catch (error) {
    if (error instanceof ApiError) throw error;

    logger.warn({ err: error }, 'Openfort session verification failed');
    throw new ApiError('UNAUTHORIZED', 'Invalid Openfort access token.');
  }
}

export function deleteOpenfortUser(openfortUserId: string) {
  return getOpenfortClient().iam.users.delete(openfortUserId);
}

export class OpenfortEncryptionSessionError extends ApiError {
  readonly service = 'openfort-shield';
  readonly envVars: string[];
  readonly hint: string;

  constructor(
    message: string,
    hint: string,
    options: { cause?: unknown } = {}
  ) {
    super('SERVICE_UNAVAILABLE', message, {
      detail: hint,
      cause: options.cause,
    });
    this.name = 'OpenfortEncryptionSessionError';
    this.envVars = [
      'NEXT_PUBLIC_SHIELD_API_KEY',
      'SHIELD_SECRET_KEY',
      'SHIELD_ENCRYPTION_SHARE',
    ];
    this.hint = hint;
  }
}

function isInvalidShieldTokenError(error: unknown) {
  const message =
    error instanceof Error
      ? error.message
      : typeof error === 'string'
        ? error
        : '';

  return /invalid token|a_invalid/i.test(message);
}

export async function createOpenfortEncryptionSession() {
  const { shield } = requireServerEnv(['shield']);

  try {
    return await getOpenfortClient().createEncryptionSession(
      shield.publishableKey!,
      shield.secretKey!,
      shield.encryptionShare!,
      shield.url
    );
  } catch (error) {
    if (isInvalidShieldTokenError(error)) {
      throw new OpenfortEncryptionSessionError(
        'Openfort Shield rejected the wallet setup request.',
        'Likely cause: NEXT_PUBLIC_SHIELD_API_KEY, SHIELD_SECRET_KEY, or SHIELD_ENCRYPTION_SHARE is missing, invalid, or from a different Openfort project.',
        { cause: error }
      );
    }

    throw error;
  }
}
